function a1(r,c){let s='';while(c>0){let m=(c-1)%26;s=String.fromCharCode(65+m)+s;c=(c-m-1)/26;}return s+r;}

// Update Cash Flow Valuation inputs
const cfv = ss.getSheetByName('Cash Flow Valuation');
cfv.getRange('F6:F7').setValues([[0.03039],[0.07290961]]);
cfv.getRange('F11').setValue(0.3538);

// Decrease Year 10 revenue growth rate assumptions by 2 percentage points
const bgb = ss.getSheetByName('Books & GAAP Bridge');
const y10Range = bgb.getRange('P12:P15');
const y10Vals = y10Range.getValues();
for (let i = 0; i < y10Vals.length; i++) {
  y10Vals[i][0] = y10Vals[i][0] - 0.02;
}
y10Range.setValues(y10Vals);

// Clear numeric data from Trading Comps except blue-font values and target company hardcoded input values
const tc = ss.getSheetByName('Trading Comps');
const rg = tc.getDataRange();
const vals = rg.getValues();
const formulas = rg.getFormulas();
const colors = rg.getFontColors();
const lr = rg.getNumRows();
const lc = rg.getNumColumns();
let targetRow = null;
for (let r = 1; r <= lr; r++) {
  if (vals[r-1][1] === 'Corvane Broadcasting Inc') { targetRow = r; break; }
}
if (!targetRow) throw new Error('Target company row not found');
let cleared = [];
for (let r = 1; r <= lr; r++) {
  for (let c = 1; c <= lc; c++) {
    const v = vals[r-1][c-1];
    const isNumeric = typeof v === 'number';
    if (!isNumeric) continue;
    const color = String(colors[r-1][c-1] || '').toLowerCase();
    const isBlue = color === '#0000ff';
    const isTargetHardcodedInput = r === targetRow && !formulas[r-1][c-1];
    if (!isBlue && !isTargetHardcodedInput) {
      tc.getRange(r,c).clearContent();
      cleared.push(a1(r,c));
    }
  }
}
SpreadsheetApp.flush();
log(JSON.stringify({
  cashFlowValuation: {
    F6: cfv.getRange('F6').getValue(),
    F7: cfv.getRange('F7').getValue(),
    F11: cfv.getRange('F11').getValue()
  },
  booksGAAPBridge: bgb.getRange('P12:P15').getValues().map(r=>r[0]),
  tradingComps: {
    targetRow,
    clearedCount: cleared.length,
    firstCleared: cleared.slice(0,25)
  }
}, null, 2));
